      SUBROUTINE THRED2(TA,COR)CC     SECOND ORDER TRANSFORMATION OF BEAM CENTROIDC ----------------------------------------------------------------------C ----------------------------------------------------------------------C     LOCAL VARIABLESC      REAL            COR(6), COT(6), TA(5,21)C ----------------------------------------------------------------------CC     SECOND ORDER TERMSC      DO 20 J = 1, 5      IND = 0      SS = 0.0      DO  10 L2 = 1, 6      DO  10 L1 = 1, L2      IND = IND + 1      SS = SS + TA(J,IND)*COR(L1)*COR(L2)   10 CONTINUE      COT(J) = SS   20 CONTINUE      COT(6) = 0.0C      DO 50 J = 1, 6   50 COR(J) = COT(J)C      RETURN      END